function waveBanner(){if(!state.waveBanner)return;let x=W/2,y=Math.max(190,H*.25);ctx.save();ctx.globalAlpha=Math.min(1,state.waveBanner);ctx.fillStyle='#173c32ef';ctx.fillRect(x-145,y-28,290,60);ctx.textAlign='center';ctx.fillStyle='#ffe094';ctx.font='bold 18px system-ui';ctx.fillText('Волна '+state.wave+' отражена!',x,y-3);ctx.fillStyle='#d5e5cb';ctx.font='12px system-ui';ctx.fillText('Доход '+(state.stats.waves.at(-1)?.earned||0)+' ● · шахты '+(state.stats.waves.at(-1)?.mineIncome||0)+' ●',x,y+17);ctx.restore()}
for(let [id,key]of[['battleVolume','battle'],['ambientVolume','ambient']]){$(id).value=Math.round((key==='battle'?battleVolume:ambientVolume)*100);$(id).oninput=()=>{let value=Math.max(0,Math.min(100,Number($(id).value)||0))/100;if(key==='battle')battleVolume=value;else ambientVolume=value;localStorage.setItem('bastion-volumes',JSON.stringify({battle:battleVolume,ambient:ambientVolume}));$(id+'Value').textContent=Math.round(value*100)+'%'};$(id+'Value').textContent=$(id).value+'%'}

function separateFriends(dt){let cells=new Map();for(let f of friends){if(f.emerge)continue;let key=Math.floor(f.pos/18),bucket=cells.get(key)||[];for(let g of bucket){let dx=f.x-g.x,dy=f.y-g.y,d=Math.hypot(dx,dy);if(d<12){let push=(12-d)*Math.min(1,dt*8)/2,sign=dx===0?1:Math.sign(dx);f.lane=Math.max(-30,Math.min(30,(f.lane||0)+sign*push));g.lane=Math.max(-30,Math.min(30,(g.lane||0)-sign*push));f.pos=Math.max(0,Math.min(length-80,f.pos+push));g.pos=Math.max(0,g.pos-push)}}bucket.push(f);cells.set(key,bucket)}}

function changeSector(){let oldLength=length;setMap((mapIndex+1)%6,Math.floor(state.wave/30)%3);for(let i=0;i<buildings.length;i++){buildings[i].x=layoutSpots[i][0];buildings[i].y=layoutSpots[i][1]}for(let f of friends){f.pos=Math.min(length-80,f.pos/oldLength*length);let p=point(f.pos);let next=point(Math.min(length,f.pos+5)),dx=next.x-p.x,dy=next.y-p.y,norm=Math.hypot(dx,dy)||1;f.x=p.x-dy/norm*(f.lane||0);f.y=p.y+dx/norm*(f.lane||0);f.emerge=null;f.targetId=null}let entry=point(80);hero.x=hero.tx=entry.x;hero.y=hero.ty=entry.y;addGold(coins.reduce((n,c)=>n+c.value,0));coins=[];traps=[];tracks=[];selectedBuilding=null;configureCamera();$('mapSelect').value=String(mapIndex);state.sectorNotice=maps[mapIndex].name;state.transitionFx=1.4;message('Новый рубеж: '+maps[mapIndex].name);save()}

const buildCatalog={barracks:{name:'Казарма',cost:60,info:'Создаёт мечников; улучшение открывает рыцарей.'},archer:{name:'Лучная башня',cost:100,info:'Быстрые выстрелы по одиночным целям.'},cannon:{name:'Пушка',cost:150,info:'Урон по группе врагов.'},mine:{name:'Золотая шахта',cost:90,info:'6 золота каждые 10 секунд прямо в казну.'},workshop:{name:'Мастерская',cost:120,info:'Чинит здания в радиусе 240; ветка ремонта расширяет его до 300.'}};
function promptNearbyPlot(){let b=buildings.find(v=>Math.hypot(v.x-hero.x,v.y-hero.y)<60&&(!v.built||v.level<3));if(!b){promptedPlot=null;return}if(state.gold>=Math.min(...optionsFor(b).map(v=>v.cost))&&hero.hp>0&&Math.hypot(hero.tx-hero.x,hero.ty-hero.y)<8&&promptedPlot!==(b.slotId||b.id)&&(!b.choiceMade||b.built&&!b.upgradeChoice)){promptedPlot=b.slotId||b.id;openPlotChoice(b)}}
function optionsFor(b){if(!b.built)return(b.category==='economy'?['mine','workshop']:['barracks','archer','cannon']).map(kind=>({kind,...buildCatalog[kind]}));let types=b.id==='archer'||b.id==='cannon'?[['rapid','Скорострельность','Чаще стреляет, меньший урон выстрела.'],['heavy','Тяжёлые выстрелы','Больше урона; медленнее перезарядка.']]:b.id==='mine'?[['yield','Богатая жила','+7 золота за выплату; реже, но больше за раз.'],['fast','Быстрая добыча','Выплата каждые 6 секунд.']]:b.id==='workshop'?[['repair','Усиленный ремонт','+12 к ремонту; радиус увеличен с 240 до 300.'],['heal','Лазарет','Дополнительно лечит героя рядом.']]:[['guard','Рыцарская школа','Стойкие рыцари со щитами.'],['recruit','Быстрый набор','Отряды по 4 мечника.']];return types.map(([kind,name,info])=>({kind,name,info,cost:60*b.level-(b.upgradePaid||0)}))}
function openPlotChoice(b){if(!playing)return;plotChoice=b;promptedPlot=b.slotId||b.id;pausedByPlot=!paused;paused=true;$('plotTitle').textContent=b.built?b.name+(b.level<3?' · улучшение до '+(b.level+1):' · максимальный уровень'):'Что построить?';let options=b.built&&b.level>=3?[]:optionsFor(b);$('plotCards').innerHTML=options.map((v,i)=>'<button data-build-choice="'+i+'" '+(state.gold<v.cost?'disabled':'')+'><b>'+v.name+'</b><span>'+v.cost+' ●</span><p>'+v.info+'</p></button>').join('');$('rebuildPlot').classList.toggle('hidden',!b.built);$('rebuildPlot').textContent='Перестроить · вернуть '+rebuildRefund(b)+' ●';$('rebuildPlot').removeAttribute?.('data-confirm');$('targetPriorityRow').classList.toggle('hidden',!b.built||!['archer','cannon'].includes(b.id));$('targetPriority').value=b.targetPriority||'smart';$('plotPopup').classList.remove('hidden');document.querySelectorAll?.('[data-build-choice]').forEach(el=>el.onclick=()=>choosePlotOption(Number(el.getAttribute('data-build-choice'))))}
function choosePlotOption(index){let b=plotChoice;if(!b)return;let v=optionsFor(b)[index];if(!v||state.gold<v.cost)return;if(!b.built){Object.assign(b,{id:v.kind,name:v.name,cost:v.cost,choiceMade:true,paid:0,timer:0})}else{b.pendingSpec=v.kind;b.upgradeChoice=true}hero.tx=b.x;hero.ty=b.y;selectedBuilding=b.slotId||b.id;closePlotChoice();save();message('Выбрано: '+v.name+' · стой у площадки для оплаты')}
function closePlotChoice(){$('plotPopup').classList.add('hidden');plotChoice=null;if(pausedByPlot){paused=false;pausedByPlot=false}$('pause').textContent=paused?'▶':'Ⅱ'}
$('plotClose').onclick=closePlotChoice;
function sectorTransition(){if(!state.transitionFx)return;ctx.save();ctx.fillStyle='rgba(14,31,35,'+Math.max(0,state.transitionFx/1.4*.5)+')';ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffe6a3';ctx.font='bold 20px system-ui';ctx.textAlign='center';ctx.fillText(maps[mapIndex].name,W/2,H*.28);ctx.restore()}

function mineIncome(b){return 4+b.level*2+meta.kingdom.mint*2+(b.spec==='yield'?7:0)}
function rebuildRefund(b){return b.built?Math.floor((b.cost+(b.level>=2?60:0)+(b.level>=3?120:0)+(b.upgradePaid||0))*.5):0}
function rebuildPlot(){let b=plotChoice;if(!b?.built)return;if($('rebuildPlot').getAttribute?.('data-confirm')!=='yes'){$('rebuildPlot').setAttribute('data-confirm','yes');$('rebuildPlot').textContent='Подтвердить снос · вернуть '+rebuildRefund(b)+' ●';return}let amount=rebuildRefund(b);state.gold+=amount;Object.assign(b,{built:false,choiceMade:false,paid:0,upgradePaid:0,upgradeChoice:false,pendingSpec:null,spec:null,level:1,hp:100,max:100,timer:0,charge:0,deposit:0,totalIncome:0});closePlotChoice();promptedPlot=null;selectedBuilding=b.slotId||b.id;save();hud();message('Площадка освобождена · возвращено '+amount+' ●')}
$('rebuildPlot').onclick=rebuildPlot;
function towerTarget(b,range){let incoming=new Map();for(let shot of shots)if(shot.buildingId&&shot.target)incoming.set(shot.target,(incoming.get(shot.target)||0)+shot.damage);let best=null,score=-Infinity,rr=range*range;for(let e of enemies){let d=(e.x-b.x)**2+(e.y-b.y)**2;if(e.dead||d>=rr)continue;let progress=e.pos/(routes[e.route||0]?.length||length),value=b.targetPriority==='nearest'?1-d/rr:b.targetPriority==='strongest'?e.hp/1000:b.targetPriority==='front'?progress:progress+(e.siege?.25:0)+(e.boss?.2:0)+(b.spec==='heavy'&&e.armored?.1:0);value-=((incoming.get(e)||0)>=e.hp?2:0);if(value>score){score=value;best=e}}return best}
function branchDecor(b,x,y){if(!b.spec)return;if(b.id==='mine'){if(b.spec==='yield'){box(x+45,y+32,22,18,14,['#ad8149','#79552f','#554428']);for(let i=0;i<5;i++){let q=proj(x+48+i*3,y+39,18+(i%2)*3);oval(q[0],q[1],3*scale,3*scale,'#efcb63')}}else{for(let i=0;i<2;i++){let q=proj(x+48,y+18+i*19,16);ctx.strokeStyle='#80c1d1';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(...q,9*scale,9*scale,0,0,Math.PI*2);ctx.stroke();wheelSpokes(q[0],q[1],8*scale,time*1.6)}}}if(b.id==='workshop'){if(b.spec==='heal'){poly([[x+8,y+42,25],[x+45,y+42,25],[x+45,y+55,18],[x+8,y+55,18]],'#c1d8b7');line([[x+27,y+56,13],[x+27,y+56,26]],'#7aa571',4);line([[x+21,y+56,20],[x+33,y+56,20]],'#7aa571',4)}else{box(x+44,y+40,22,13,12,['#a2ada8','#65736b','#3d4f46']);line([[x+47,y+44,15],[x+64,y+44,15]],'#e0d8bd',4);crate(x+53,y+16)}}let c=b.spec==='rapid'||b.spec==='fast'?'#8bd3df':b.spec==='heavy'||b.spec==='yield'?'#e7bf6b':b.spec==='heal'?'#b2dda0':'#a7b9d1';line([[x-3,y+15,0],[x-3,y+15,50]],'#6b5439',2);poly([[x-3,y+15,50],[x+15,y+15,46],[x+15,y+15,32],[x-3,y+15,35]],c);if(b.spec==='heavy'&&b.id==='archer'){box(x+7,y+6,42,5,7,['#bb985a','#927844','#665936'],50+b.level*12);line([[x+7,y+6,60+b.level*12],[x+49,y+6,60+b.level*12]],'#d8b46a',3)}if(b.spec==='rapid'&&['archer','cannon'].includes(b.id)){for(let i=0;i<3;i++)box(x+52,y+20+i*8,10,5,6,['#9fbec6','#597e8c','#355b69'])}}
$('batterySaver').checked=batterySaver;$('batterySaver').onchange=()=>{batterySaver=!!$('batterySaver').checked;localStorage.setItem('bastion-battery',batterySaver?'1':'0');resize();message(batterySaver?'Экономия батареи: 30 кадров/с':'Обычная частота кадров')};

function repairRange(b){return b.spec==='repair'?300:240}
function mineProgress(b){if(b.id!=='mine'||!b.built)return;let q=proj(b.x,b.y+29,8),interval=b.spec==='fast'?6:10,progress=1-Math.max(0,Math.min(interval,b.timer))/interval;ctx.save();ctx.lineWidth=3;ctx.strokeStyle='#1e3c32';ctx.beginPath();ctx.ellipse(...q,15*scale*zoom,15*verticalScale*zoom,0,0,Math.PI*2);ctx.stroke();ctx.strokeStyle='#f4d573';ctx.beginPath();ctx.ellipse(...q,15*scale*zoom,15*verticalScale*zoom,0,-Math.PI/2,-Math.PI/2+Math.PI*2*progress);ctx.stroke();ctx.restore()}
function affordablePlotMarker(){let best=null,distance=105;for(let b of buildings){let cost=b.choiceMade?b.cost-b.paid:b.category==='economy'?90:60,d=Math.hypot(b.x-hero.x,b.y-hero.y);if(!b.built&&state.gold>=cost&&d<distance){best=b;distance=d}}if(!best)return;let q=proj(best.x,best.y);ctx.save();ctx.strokeStyle='#ffe194';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(...q,35*scale*zoom,28*verticalScale*zoom,0,0,Math.PI*2);ctx.stroke();ctx.restore()}
$('targetPriority').onchange=()=>{if(!plotChoice?.built)return;let value=$('targetPriority').value;if(!['smart','front','nearest','strongest'].includes(value))return;plotChoice.targetPriority=value;save();message('Приоритет цели сохранён')};
